/**
 * Adds or removes a member entry from a collection.
 */
sealed class CollectionAction {
    data class Add(
        val v1: kotlin.Long,
    ) : CollectionAction() {
        companion object
    }

    data class Remove(
        val v1: kotlin.Long,
    ) : CollectionAction() {
        companion object
    }

    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCollectionAction : FfiConverterRustBuffer<CollectionAction> {
    override fun read(buf: ByteBuffer): CollectionAction =
        when (buf.getInt()) {
            1 -> {
                CollectionAction.Add(
                    FfiConverterLong.read(buf),
                )
            }

            2 -> {
                CollectionAction.Remove(
                    FfiConverterLong.read(buf),
                )
            }

            else -> {
                throw RuntimeException("invalid enum value, something is very wrong!!")
            }
        }

    override fun allocationSize(value: CollectionAction): ULong =
        when (value) {
            is CollectionAction.Add -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterLong.allocationSize(value.v1)
                )
            }

            is CollectionAction.Remove -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterLong.allocationSize(value.v1)
                )
            }
        }

    override fun write(
        value: CollectionAction,
        buf: ByteBuffer,
    ) {
        when (value) {
            is CollectionAction.Add -> {
                buf.putInt(1)
                FfiConverterLong.write(value.v1, buf)
                Unit
            }

            is CollectionAction.Remove -> {
                buf.putInt(2)
                FfiConverterLong.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}

/**
 * Errors surfaced across the FFI boundary.
 *
 * `NotFound` is returned when an entry or collection id doesn't exist;
 * the remaining variants cover database, migration, and timestamp failures.
 */
sealed class Exception(
    message: String,
) : kotlin.Exception(message) {
    class DatabaseException(
        message: String,
    ) : Exception(message)

    class MigrationException(
        message: String,
    ) : Exception(message)

    class NotFound(
        message: String,
    ) : Exception(message)

    class TimeStampConversionException(
        message: String,
    ) : Exception(message)

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<Exception> {
        override fun lift(error_buf: RustBuffer.ByValue): Exception = FfiConverterTypeError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeError : FfiConverterRustBuffer<Exception> {
    override fun read(buf: ByteBuffer): Exception =
        when (buf.getInt()) {
            1 -> Exception.DatabaseException(FfiConverterString.read(buf))
            2 -> Exception.MigrationException(FfiConverterString.read(buf))
            3 -> Exception.NotFound(FfiConverterString.read(buf))
            4 -> Exception.TimeStampConversionException(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }

    override fun allocationSize(value: Exception): ULong = 4UL

    override fun write(
        value: Exception,
        buf: ByteBuffer,
    ) {
        when (value) {
            is Exception.DatabaseException -> {
                buf.putInt(1)
                Unit
            }

            is Exception.MigrationException -> {
                buf.putInt(2)
                Unit
            }

            is Exception.NotFound -> {
                buf.putInt(3)
                Unit
            }

            is Exception.TimeStampConversionException -> {
                buf.putInt(4)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}

