            throw RuntimeException("invalid enum value, something is very wrong!!", e)
        }

    override fun allocationSize(value: MediaKind) = 4UL

    override fun write(
        value: MediaKind,
        buf: ByteBuffer,
    ) {
        buf.putInt(value.ordinal + 1)
    }
}

