/**
 * Tag filtering: `Or` matches entries with any of the listed tags,
 * `And` requires all of them.
 */
sealed class TagFilter {
    data class Or(
        val v1: List<kotlin.String>,
    ) : TagFilter() {
        companion object
    }

    data class And(
        val v1: List<kotlin.String>,
    ) : TagFilter() {
        companion object
    }

    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeTagFilter : FfiConverterRustBuffer<TagFilter> {
    override fun read(buf: ByteBuffer): TagFilter =
        when (buf.getInt()) {
            1 -> {
                TagFilter.Or(
                    FfiConverterSequenceString.read(buf),
                )
            }

            2 -> {
                TagFilter.And(
                    FfiConverterSequenceString.read(buf),
                )
            }

            else -> {
                throw RuntimeException("invalid enum value, something is very wrong!!")
            }
        }

    override fun allocationSize(value: TagFilter): ULong =
        when (value) {
            is TagFilter.Or -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterSequenceString.allocationSize(value.v1)
                )
            }

            is TagFilter.And -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterSequenceString.allocationSize(value.v1)
                )
            }
        }

    override fun write(
        value: TagFilter,
        buf: ByteBuffer,
    ) {
        when (value) {
            is TagFilter.Or -> {
                buf.putInt(1)
                FfiConverterSequenceString.write(value.v1, buf)
                Unit
            }

            is TagFilter.And -> {
                buf.putInt(2)
                FfiConverterSequenceString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}

