/**
 * @suppress
 */
public object FfiConverterMapTypeMediaKindUInt : FfiConverterRustBuffer<Map<MediaKind, kotlin.UInt>> {
    override fun read(buf: ByteBuffer): Map<MediaKind, kotlin.UInt> {
        val len = buf.getInt()
        return buildMap<MediaKind, kotlin.UInt>(len) {
            repeat(len) {
                val k = FfiConverterTypeMediaKind.read(buf)
                val v = FfiConverterUInt.read(buf)
                this[k] = v
            }
        }
    }

    override fun allocationSize(value: Map<MediaKind, kotlin.UInt>): ULong {
        val spaceForMapSize = 4UL
        val spaceForChildren =
            value
                .map { (k, v) ->
                    FfiConverterTypeMediaKind.allocationSize(k) +
                        FfiConverterUInt.allocationSize(v)
                }.sum()
        return spaceForMapSize + spaceForChildren
    }

    override fun write(
        value: Map<MediaKind, kotlin.UInt>,
        buf: ByteBuffer,
    ) {
        buf.putInt(value.size)
        // The parens on `(k, v)` here ensure we're calling the right method,
        // which is important for compatibility with older android devices.
        // Ref https://blog.danlew.net/2017/03/16/kotlin-puzzler-whose-line-is-it-anyways/
        value.forEach { (k, v) ->
            FfiConverterTypeMediaKind.write(k, buf)
            FfiConverterUInt.write(v, buf)
        }
    }
}

public typealias UtcDateTime = Instant

/**
 * @suppress
 */
public object FfiConverterTypeUtcDateTime : FfiConverter<UtcDateTime, Long> {
    override fun lift(value: Long): UtcDateTime {
        val builtinValue = FfiConverterLong.lift(value)
        return Instant.ofEpochSecond(builtinValue)
    }

    override fun lower(value: UtcDateTime): Long {
        val builtinValue = value.epochSecond
        return FfiConverterLong.lower(builtinValue)
    }

    override fun read(buf: ByteBuffer): UtcDateTime {
        val builtinValue = FfiConverterLong.read(buf)
        return Instant.ofEpochSecond(builtinValue)
    }

    override fun allocationSize(value: UtcDateTime): ULong {
        val builtinValue = value.epochSecond
        return FfiConverterLong.allocationSize(builtinValue)
    }

    override fun write(
        value: UtcDateTime,
        buf: ByteBuffer,
    ) {
        val builtinValue = value.epochSecond
        FfiConverterLong.write(builtinValue, buf)
    }
}
